<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <div class="page-shell">
    <header>
      <p class="eyebrow">Computer languages quiz</p>
      <h1>Choose every answer that fits.</h1>
      <p class="intro">Test your knowledge of programming, markup, query, and scripting languages. Some questions have more than one correct answer.</p>
    </header>

    <main id="main-content">
      <section class="quiz-card" aria-labelledby="quiz-title">
        <h2 id="quiz-title" class="visually-hidden">Three question computer languages quiz</h2>
        <form id="quiz-form" novalidate></form>
      </section>
    </main>
  </div>

  <script>
    const quizQuestions = [
      {
        id: "compiled-languages",
        question: "Which of these are commonly compiled programming languages?",
        helpText: "Select every language that is typically transformed into machine code or bytecode before it runs.",
        choices: ["C", "HTML", "Rust", "SQL"]
      },
      {
        id: "web-languages",
        question: "Which languages are core technologies used to build web pages?",
        choices: ["HTML", "CSS", "JavaScript", "Bash"]
      },
      {
        id: "query-languages",
        question: "Which of these are used to query or work with structured data?",
        choices: ["SQL", "GraphQL", "Python", "Markdown"]
      }
    ];

    function Choice({ questionId, choice }) {
      const optionId = `${questionId}-${choice.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`;

      return `
        <label class="choice" for="${optionId}">
          <input id="${optionId}" name="${questionId}" type="checkbox" value="${choice}">
          <span class="choice-text">${choice}</span>
        </label>
      `;
    }

    function QuestionField({ id, question, helpText, choices }, index) {
      const helpId = `${id}-help`;
      const describedBy = helpText ? ` aria-describedby="${helpId}"` : "";

      return `
        <div class="form-field">
          <fieldset${describedBy}>
            <legend>${index + 1}. ${question}</legend>
            ${helpText ? `<p class="help-text" id="${helpId}">${helpText}</p>` : ""}
            <div class="choices">
              ${choices.map((choice) => Choice({ questionId: id, choice })).join("")}
            </div>
          </fieldset>
        </div>
      `;
    }

    function QuizForm({ questions }) {
      return `
        ${questions.map(QuestionField).join("")}
        <div class="form-actions">
          <button type="submit">Submit answers</button>
          <p class="result" id="quiz-result" aria-live="polite">No answers submitted yet.</p>
        </div>
      `;
    }

    const form = document.querySelector("#quiz-form");
    form.innerHTML = QuizForm({ questions: quizQuestions });

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const selectedCount = quizQuestions.reduce((total, question) => {
        return total + form.querySelectorAll(`input[name="${question.id}"]:checked`).length;
      }, 0);

      const result = document.querySelector("#quiz-result");
      result.textContent = selectedCount === 1
        ? "You selected 1 answer."
        : `You selected ${selectedCount} answers.`;
    });
  </script>
</body>
